def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Aggregate counts over the whole match.
    opp_d = 0
    my_d = 0
    cc = 0
    for i in range(n):
        a, b = history[i]
        if b == 'D':
            opp_d += 1
        if a == 'D':
            my_d += 1
        if a == 'C' and b == 'C':
            cc += 1

    # Recent history (last 12 rounds) gives the most reliable signal.
    look = 12 if n >= 12 else n
    recent_opp_d = 0
    recent_my_d = 0
    run_opp_d = 0
    run_opp_c = 0
    for i in range(n - look, n):
        a, b = history[i]
        if b == 'D':
            recent_opp_d += 1
        if a == 'D':
            recent_my_d += 1
    # Current trailing runs of opponent's moves.
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            run_opp_d += 1
        else:
            break
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            run_opp_c += 1
        else:
            break

    last_opp = history[-1][1]
    last_my = history[-1][0]
    remaining = 100 - n

    # Endgame: defect against non-perfect partners to grab the last points.
    if remaining <= 3:
        if opp_d <= 1 and cc >= n - 2:
            return 'C'
        return 'D'

    # Perfect / near-perfect cooperator: exploit late, but keep cooperation
    # going through the middle so the mutual-CC stream continues.
    if opp_d == 0:
        if n < 90:
            return 'C'
        return 'D'
    if opp_d == 1 and n >= 20 and remaining > 15:
        return 'C'

    # Almost-always-defector: defect, with very rare cheap probes.
    if opp_d * 10 >= n * 9:
        if last_opp == 'C':
            return 'C'
        if remaining > 10 and (n % 9 == 3):
            return 'C'
        return 'D'

    # Strongly cooperative opponent with a rare defection: forgive quickly,
    # but retaliate immediately if a defection just happened.
    if opp_d * 5 <= n:
        if last_opp == 'D':
            # One-shot retaliation; then return to cooperation to protect
            # the long CC stream rather than spiraling.
            if run_opp_d >= 2:
                return 'D'
            return 'D'
        # If we ourselves defected recently, return to C to repair.
        if last_my == 'D':
            return 'C'
        return 'C'

    # Opponent is mixed. Use a forgiving, retaliatory scheme with repair.
    if last_opp == 'D':
        # Long defection run: stay in D, but periodically conciliate to
        # give a reactive opponent a chance to return to cooperation.
        if run_opp_d >= 4:
            if remaining > 5 and (n % 6 == 0):
                return 'C'
            return 'D'
        if run_opp_d >= 2:
            return 'D'
        # Single recent defection: retaliate once, then try to repair.
        if last_my == 'D':
            # We already punished; extend a cooperative hand.
            return 'C'
        return 'D'

    # Opponent just cooperated. Preserve mutual cooperation when possible.
    if last_my == 'D':
        if recent_opp_d * 3 >= look:
            # Opponent still fairly aggressive; defect to avoid being exploited.
            return 'D'
        return 'C'

    # Both cooperated last round. Occasionally probe a very compliant
    # opponent, but keep probes rare so the CC stream dominates.
    if recent_opp_d == 0 and n >= 30 and remaining > 12:
        if rng.random() < 0.05:
            return 'D'
        return 'C'

    # If mutual cooperation has been common, keep it.
    if cc * 2 >= n:
        return 'C'

    # Mixed-case fallback: retaliate against recent defection, otherwise C.
    if recent_opp_d * 3 >= look:
        if rng.random() < 0.25:
            return 'C'
        return 'D'
    return 'C'
